import { createGate, QuotaExceededError } from '/mnt/c/claude_gsb/cla10/solverA/task012/src/index.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let failures = 0;
function check(name, cond) {
  if (cond) console.log('PASS', name);
  else { console.log('FAIL', name); failures += 1; }
}

// 1. Over-limit single acquire borrows own -> direct parent -> grandparent -> pool
{
  const root = createGate({ limit: 10, windowMs: 1000 });
  const p = createGate({ limit: 3, windowMs: 1000, parent: root });
  const a = createGate({ limit: 2, windowMs: 1000, parent: p });
  await p.acquire(2); // p headroom left: 1
  const h = await a.acquire(5); // own 2 + p lend 1 + pool 2
  check('chain borrow: a inFlight 5', a.stats().inFlight === 5);
  check('chain borrow: p inFlight 3', p.stats().inFlight === 3);
  check('chain borrow: granted on a', a.stats().granted === 1);
  h.release();
  check('chain borrow: a back to 0', a.stats().inFlight === 0);
  check('chain borrow: p back to 2', p.stats().inFlight === 2);
}

// 2. Over-limit is not a RangeError; pool shortfall refuses QUOTA_EXCEEDED (wait 0)
{
  const root = createGate({ limit: 3, windowMs: 1000 });
  const a = createGate({ limit: 2, windowMs: 1000, parent: root });
  await a.acquire(2);
  let err;
  try { await a.acquire(2); } catch (e) { err = e; }
  check('over-limit refused QUOTA_EXCEEDED', err instanceof QuotaExceededError && err.code === 'QUOTA_EXCEEDED');
  check('refused counted on a', a.stats().refused === 1);
  let threw = false;
  try { await a.acquire(99); } catch (e) { threw = e instanceof QuotaExceededError; }
  check('units beyond pool cap also QEE not RangeError', threw);
}

// 3. Validation: type vs range
{
  const g = createGate({ limit: 2, windowMs: 1000 });
  const isT = (fn) => { try { fn(); return false; } catch (e) { return e instanceof TypeError; } };
  const isR = (fn) => { try { fn(); return false; } catch (e) { return e instanceof RangeError; } };
  check('acquire(1.5) RangeError', isR(() => g.acquire(1.5)));
  check('acquire(0) RangeError', isR(() => g.acquire(0)));
  check('acquire(-1) RangeError', isR(() => g.acquire(-1)));
  check("acquire('1') TypeError", isT(() => g.acquire('1')));
  check('acquire({}) TypeError', isT(() => g.acquire({})));
  check('acquire(99999) no throw', !isT(() => g.acquire(99999)) && !isR(() => g.acquire(99999)));
}

// 4. Queued over-limit single granted at pool flip, reserving meanwhile
{
  const root = createGate({ limit: 5, windowMs: 60, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  await root.acquire(4);
  const p = a.acquire(1); // own 1 reserved, pool 4+1=5
  check('queued single: waiting 1', a.stats().waiting === 1);
  check('queued single: reserved 1 at member', a.stats().reserved === 1);
  check('queued single: root reserved 0', root.stats().reserved === 0);
  check('queued single: inFlight 0', a.stats().inFlight === 0);
  const h = await p;
  check('queued single granted at flip', a.stats().granted === 1 && a.stats().inFlight === 1);
  check('reserved consumed', a.stats().reserved === 0);
  h.release();
}

// 5. Queued over-limit single that does not fit yet is a hard barrier
{
  const root = createGate({ limit: 3, windowMs: 40, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  const pBig = a.acquire(4).then(() => 'big', (e) => e.code); // never fits pool 3
  let s1 = false;
  const p1 = root.acquire(1).then(() => { s1 = true; });
  await sleep(120); // several flips; big blocks, s1 cannot pass
  check('hard barrier: later small not granted', s1 === false);
  const ac = new AbortController();
  // pBig has no signal; let it expire instead: wait caps differ per gate.
  // Instead cancel by timeout — use expiry: give it time.
  await Promise.race([pBig, sleep(5000)]);
  await p1;
  check('hard barrier clears after big settles', s1 === true);
}

// 6. Parent window flip reclaims borrowed part of a single occupation
{
  const root = createGate({ limit: 5, window: 1000, windowMs: 1000 });
  const p = createGate({ limit: 3, windowMs: 40, parent: root });
  const a = createGate({ limit: 2, windowMs: 10000, parent: p });
  const own = await a.acquire(2);
  const borrowed = await a.acquire(2); // own 0 (used 2) -> p lend 1 + pool 1
  check('a inFlight 4', a.stats().inFlight === 4);
  await sleep(80); // p window flips twice: lends reclaimed
  check('a inFlight 2 after parent flip', a.stats().inFlight === 2);
  borrowed.release();
  check('release after reclaim no double subtract', a.stats().inFlight === 2);
  own.release();
  check('a inFlight 0', a.stats().inFlight === 0);
}

// 7. Child limit shrink does not refuse child's over-limit queued single
{
  const root = createGate({ limit: 5, windowMs: 1000, maxWaitMs: 5000 });
  const a = createGate({ limit: 3, windowMs: 1000, maxWaitMs: 5000, parent: root });
  await root.acquire(5);
  const p = a.acquire(3); // queued, equal to limit here; shrink below it
  a.updateLimit(1);
  check('no refusal after child shrink', a.stats().refused === 0 && a.stats().waiting === 3);
  // root shrink below the queued size refuses it
  root.updateLimit(2);
  const code = await p.then(() => null, (e) => e.code);
  check('root shrink refuses oversized queued single', code === 'QUOTA_EXCEEDED');
  check('refused counted once on owner', a.stats().refused === 1);
}

// 8. Arrival order across gates still holds with chain borrowing
{
  const root = createGate({ limit: 2, windowMs: 60, maxWaitMs: 5000 });
  const p = createGate({ limit: 2, windowMs: 60, maxWaitMs: 5000, parent: root });
  const a = createGate({ limit: 1, windowMs: 60, maxWaitMs: 5000, parent: p });
  await root.acquire(2);
  const order = [];
  const p1 = a.acquire(2).then((h) => { order.push('a'); return h; }); // over child limit, borrows
  const p2 = root.acquire(1).then((h) => { order.push('root'); return h; });
  await sleep(90);
  check('a served first at flip', JSON.stringify(order) === JSON.stringify(['a']));
  const [ha] = await Promise.all([p1]);
  await p2;
  check('order kept', JSON.stringify(order) === JSON.stringify(['a', 'root']));
  ha.release();
}

// 9. Pre-aborted over-limit acquire settles CANCELLED without touching quota
{
  const root = createGate({ limit: 3, windowMs: 1000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 1000, parent: root });
  await a.acquire(2);
  const ac = new AbortController(); ac.abort();
  const code = await a.acquire(5, ac.signal).then(() => null, (e) => e.code);
  check('pre-aborted CANCELLED', code === 'CANCELLED');
  check('no waiting/reserved/inflight change', a.stats().waiting === 0 && a.stats().reserved === 0 && a.stats().inFlight === 2);
}

// 10. Expiry of queued over-limit single releases holds
{
  const root = createGate({ limit: 3, windowMs: 10000, maxWaitMs: 30 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 30, parent: root });
  await root.acquire(3);
  const code = await a.acquire(3).then(() => null, (e) => e.code); // pool can't cover, expires
  check('WAIT_EXPIRED', code === 'WAIT_EXPIRED');
  check('holds released: pool still 3/3 used, reserved 0', root.stats().reserved === 0 && a.stats().reserved === 0);
  check('waiting 0', a.stats().waiting === 0);
}

process.exit(failures ? 1 : 0);

