import { createGate, QuotaExceededError } from '/mnt/c/claude_gsb/cla10/solverA/task012/src/index.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const keepAlive = setInterval(() => {}, 1000);
let failures = 0;
function check(name, cond) {
  if (cond) console.log('PASS', name);
  else { console.log('FAIL', name); failures += 1; }
}

// A. Reparent migrates a queued single whose old hold lent from an old-family
//    ancestor; it re-gathers in the new family and grants at the new flip.
{
  const oldRoot = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000 });
  const p = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const child = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000, parent: p });
  const newRoot = createGate({ limit: 3, windowMs: 60, maxWaitMs: 5000 });
  await oldRoot.acquire(1);
  // wants 3: own 1 + p lend 0 (p own headroom? p limit 1 unused -> lends 1) + oldRoot lend 0 + pool 1 -> needs 3, pool full -> queues
  const pr = child.acquire(3);
  check('queued before move', child.stats().waiting === 3);
  p.reparent(newRoot); // whole subtree p+child moves
  check('still queued after move', child.stats().waiting === 3);
  check('no reservation leaked in old family', oldRoot.stats().reserved === 0);
  const h = await pr;
  check('granted in new family', child.stats().granted === 1 && child.stats().inFlight === 3);
  h.release();
}

// B. Aborting a queued single releases its whole hold
{
  const root = createGate({ limit: 3, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: root });
  await root.acquire(3);
  const ac = new AbortController();
  const p = a.acquire(1, ac.signal); // own 1 reserved; waits behind pool-full? 3+1>3 -> can't gather -> queues with no hold
  ac.abort();
  const code = await p.then(() => null, (e) => e.code);
  check('cancel code', code === 'CANCELLED');
  check('waiting 0, reserved 0', a.stats().waiting === 0 && a.stats().reserved === 0 && root.stats().reserved === 0);
}

// B2. Aborting a queued single that DID hold quota (blocked behind earlier arrival)
